function CERTIFY_UNIQUENESS(data, eps, C, Q0, M):
    V <- [ chi in data : Q0 <= q(chi) <= M and beta(chi) >= 1 - q(chi)^(-eps) ]
    if |V| <= 1: return ('unique', V)
    for each distinct pair {a, b} in V:
        ceiling <- 1 - C / log(q(a) * q(b))
        if min(beta(a), beta(b)) > ceiling:
            return ('coexisting pair', (a, b))
    return ('consistent', V)

